    pub fn handle_trade(&mut self, client: &Value, message: &indexmap::IndexMap<String, Value>) {
        let __pro_message: &indexmap::IndexMap<String, Value> = message;
        //
        //     {
        //         "e": "trade",
        //         "E": 1776104608321,
        //         "s": "ETHUSDT",
        //         "d": [
        //             {
        //                 "T": 1776104608298,
        //                 "t": "41099265-7985-4f4c-af93-2cc3bc1cf13b",
        //                 "p": "2225.15",
        //                 "q": "0.02525",
        //                 "v": "56.1850375",
        //                 "m": false
        //             }
        //         ]
        //     }
        //
        let market: crate::types::Market = self.get_market_from_client_and_message(client, message);
        if (false) {
            return;
        }
        let symbol: String = self.safe_string_k(&market, "symbol", &[Value::Str("".into())]).as_str().unwrap_or("").to_string();
        let messageHash: String = format!("{}{}", "trade::", symbol);
        if !(self.trades.has(&symbol)) {
            let limit: i64 = self.safe_integer_k(&self.options, "tradesLimit", &[Value::Int(1000)]).as_i64().unwrap_or(1000);
            CacheStore::put(&mut self.trades, &symbol, ArrayCache::new(Value::from(limit)));
        }
        let mut tradesArray: Option<crate::pro::cache::Cache> = self.trades.at(&symbol);
        let data: Vec<crate::value::Dict> = crate::value::dict_rows(__pro_message.key_list("d"));
        let mut newTrades: Vec<Value> = Vec::new();
        {
                        let mut i: i64 = 0;
            let mut __for_first_4: bool = true;
            while { if !__for_first_4 { i += 1; } __for_first_4 = false; i < (data.len() as i64) } {
            let rawTrade: crate::value::Dict = data.get(i as usize).cloned().unwrap_or_default();
            let trade: crate::value::Dict = self.parse_ws_trade(&rawTrade, Some(&market));
            newTrades.push(Value::Dict(trade));
        }
        }
        let sorted: Vec<Value> = self.sort_by(Value::from(newTrades), Value::Str("timestamp".into()), &[]).as_array().cloned().unwrap_or_default();
        {
                        let mut j: i64 = 0;
            let mut __for_first_5: bool = true;
            while { if !__for_first_5 { j += 1; } __for_first_5 = false; j < (sorted.len() as i64) } {
            let sortedTrade: Value = sorted.get(j as usize).cloned().unwrap_or(Value::Null);
            tradesArray.append(sortedTrade);
        }
        }
        let __resolved_tradesArray = Value::from(&tradesArray);
        CacheStore::put(&mut self.trades, &symbol, tradesArray);
        client.resolve(__resolved_tradesArray, messageHash.as_str());
}

    pub fn parse_ws_trade(&self, trade: impl Into<crate::Value>, market: Option<&crate::types::Market>) -> crate::value::Dict {
        let trade: Value = trade.into();
        //
        //     {
        //         "T": 1776089287762,
        //         "t": "df4d1af1-71e8-400d-9571-f2cee2e6bea8",
        //         "p": "2203.73",
        //         "q": "7.214",
        //         "v": "15897.70822",
        //         "m": false
        //     }
        //
        let timestamp: Option<i64> = self.safe_integer_k(&trade, "T", &[]).as_i64();
        let mut symbol: Option<String> = None;
        if (market.is_some()) {
            symbol = self.safe_string_k_opt(&market, "symbol", &[]);
        }
        let isBuyerMaker: Option<bool> = self.safe_bool_k_opt(&trade, "m", &[]); // m is the isBuyerMaker flag of the REST trades, true means the taker sold
        let mut side: Option<String> = None;
        let mut takerOrMaker: Option<String> = None;
        if (isBuyerMaker.is_some()) {
            side = (if (isBuyerMaker == Some(true)) { Some("sell".to_string()) } else { Some("buy".to_string()) });
            takerOrMaker = Some("taker".to_string()); // a public trade is reported from the aggressor's side, same as parseTrade
        }
        return self.safe_trade(std::sync::Arc::new({
    let mut m = indexmap::IndexMap::new();
        m.insert("info".to_string(), trade.clone());
        m.insert("id".to_string(), self.safe_string_k(&trade, "t", &[]));
        m.insert("timestamp".to_string(), Value::from(timestamp));
        m.insert("datetime".to_string(), self.iso8601(timestamp));
        m.insert("symbol".to_string(), symbol.map(Value::from).unwrap_or(Value::Null));
        m.insert("order".to_string(), Value::Null);
        m.insert("type".to_string(), Value::Null);
        m.insert("side".to_string(), side.map(Value::from).unwrap_or(Value::Null));
        m.insert("takerOrMaker".to_string(), takerOrMaker.map(Value::from).unwrap_or(Value::Null));
        m.insert("price".to_string(), self.safe_string_k(&trade, "p", &[]));
        m.insert("amount".to_string(), self.safe_string_k(&trade, "q", &[]));
        m.insert("cost".to_string(), self.safe_string_k(trade, "v", &[]));
        m.insert("fee".to_string(), Value::Null);
    m
}), market);

    Default::default()
}

