    pub fn parse_ws_my_trade(&self, trade: &crate::value::Dict, market: Option<&crate::types::Market>) -> crate::value::Dict {
        //
        // spot
        //     {
        //         id: '738928502249620072',
        //         symbol: 'DOGEUSDT',
        //         baseCoin: 'DOGE',
        //         quoteCoin: 'USDT',
        //         orderId: '738928502174122600',
        //         orderSide: 'SELL',
        //         fillSize: '200.0',
        //         fillValue: '19.098000',
        //         fillFee: '0.01909800',
        //         direction: 'TAKER',
        //         createdTime: '1776174283564',
        //         updatedTime: '1776174283564'
        //     }
        //
        let timestamp: Option<i64> = self.safe_integer_k(&trade, "createdTime", &[]).as_i64();
        let marketId: Option<String> = self.safe_string_k_opt(&trade, "symbol", &[]);
        let mut marketType: String = "spot".to_string();
        let positionSide: Option<String> = self.safe_string_k_opt(&trade, "positionSide", &[]);
        if (positionSide.is_some()) {
            marketType = "swap".to_string();
        }
        let marketResolved: crate::types::Market = self.safe_market(marketId.as_deref(), None, &[Value::Null, Value::from(marketType.as_str())]);
        let side: Option<String> = self.safe_string_lower_k_opt(&trade, "orderSide", &[]);
        let mut fee: Option<crate::value::Dict> = None;
        let commission: Option<String> = self.safe_string_k_opt(&trade, "fillFee", &[]);
        if (commission.is_some()) {
            let commissionAsset: Option<String> = self.safe_string_k_opt(&trade, "coin", &[]);
            let mut feeCurrency: Option<String> = self.safe_currency_code(commissionAsset.as_deref(), None);
            if (marketType == "spot") {
                if (side.as_deref() == Some("buy")) {
                    feeCurrency = self.safe_string_k_opt(&marketResolved, "base", &[]);
                }  else {
                    feeCurrency = self.safe_string_k_opt(&marketResolved, "quote", &[]);
                }
            }
            fee = Some(crate::value::Dict::new({
                let mut m = indexmap::IndexMap::new();
                    m.insert("cost".to_string(), commission.map(Value::from).unwrap_or(Value::Null));
                    m.insert("currency".to_string(), feeCurrency.map(Value::from).unwrap_or(Value::Null));
                m
            }));
        }
        return self.safe_trade(std::sync::Arc::new({
    let mut m = indexmap::IndexMap::new();
        m.insert("info".to_string(), Value::Dict(trade.clone()));
        m.insert("id".to_string(), self.safe_string_k(&trade, "id", &[]));
        m.insert("timestamp".to_string(), Value::from(timestamp));
        m.insert("datetime".to_string(), self.iso8601(timestamp));
        m.insert("symbol".to_string(), crate::value::KeyRead::key_read(&&marketResolved, "symbol"));
        m.insert("order".to_string(), self.safe_string_k(&trade, "orderId", &[]));
        m.insert("type".to_string(), self.safe_string_k(&trade, "type", &[]));
        m.insert("side".to_string(), side.map(Value::from).unwrap_or(Value::Null));
        m.insert("takerOrMaker".to_string(), self.safe_string_lower_k(&trade, "direction", &[]));
        m.insert("price".to_string(), Value::Null);
        m.insert("amount".to_string(), self.safe_string_k(&trade, "fillSize", &[]));
        m.insert("cost".to_string(), self.safe_string_k(&trade, "fillValue", &[]));
        m.insert("fee".to_string(), fee.map_or(Value::Null, Value::Dict));
    m
}), None);

    Default::default()
}

